// components/Navbar.jsx
import { Link } from "react-router-dom";
import { useContext } from 'react';
import { AuthContext } from '../context/AuthContext';

function Navbar() {
  const { user, logout } = useContext(AuthContext);

  return (
    <header className="site-nav">
      <div className="site-brand">
        <Link to="/">
          <picture>
            {/* prefer user's uploaded `logo.png` if present */}
            <source srcSet="/images/logo.png" type="image/png" />
            <source srcSet="/images/pick_tory_logo.png" type="image/png" />
            <img src="/images/pick_tory_logo.svg" alt="PICK TORY" className="site-logo" />
          </picture>
        </Link>
      </div>
      <nav className="links" aria-label="주요 탐색">
        <Link to="/feed">리뷰 피드</Link>
        <Link to="/explore">탐색</Link>
        <Link to="/studio">협찬 스튜디오</Link>
        <Link to="/mypage">마이페이지</Link>
        {user ? (
          <button onClick={logout} className="btn" style={{ marginLeft: 8 }}>로그아웃</button>
        ) : (
          <>
            <Link to="/login" style={{ marginLeft: 8 }}>로그인</Link>
            <Link to="/register" style={{ marginLeft: 8 }}>회원가입</Link>
          </>
        )}

        {/* Prominent Promo / Roulette CTA */}
        <Link to="/promo" style={{ marginLeft: 12, textDecoration: 'none' }}>
          <button className="roulette-cta pulse" aria-label="쿠폰 및 룰렛 참여하기">
            <span className="icon-rotate" aria-hidden>🎡</span>
            <span className="label">쿠폰 & 룰렛</span>
          </button>
        </Link>
      </nav>
    </header>
  );
}

export default Navbar;
